int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *a = (ll*)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%lld", &a[i]);

    // dp[l][r] = maximum value obtainable if finally only one element remains
    // and it is produced from subarray [l..r], while all outside elements
    // are deleted from ends at some moments.
    //
    // Transition:
    // - keep a single original element a[i]
    // - for odd length >= 3, choose middle k as the element to operate on last
    //   so final value = dp[l][k-1] + dp[k+1][r]
    //
    // This works because the last operation inside [l..r] must be applied to
    // some interior element k, replacing it by the sum of the final survivors
    // of left and right parts. Therefore lengths must be odd.
    //
    // We also reconstruct a binary tree of merges, then emit deletions of
    // outside elements first, and recursively process inside.

    ll **dp = (ll**)malloc((N + 2) * sizeof(ll*));
    int **choice = (int**)malloc((N + 2) * sizeof(int*));
    for (int i = 0; i <= N + 1; i++) {
        dp[i] = (ll*)malloc((N + 2) * sizeof(ll));
        choice[i] = (int*)malloc((N + 2) * sizeof(int));
        for (int j = 0; j <= N + 1; j++) {
            dp[i][j] = -(1LL << 60);
            choice[i][j] = -1;
        }
    }

    for (int i = 1; i <= N; i++) {
        dp[i][i] = a[i];
        choice[i][i] = 0; // leaf
    }

    for (int len = 3; len <= N; len += 2) {
        for (int l = 1; l + len - 1 <= N; l++) {
            int r = l + len - 1;
            ll best = -(1LL << 60);
            int bestk = -1;
            for (int k = l + 1; k <= r - 1; k++) {
                if (((k - l) & 1) == 1 && ((r - k) & 1) == 1) {
                    ll cand = dp[l][k - 1] + dp[k + 1][r];
                    if (cand > best) {
                        best = cand;
                        bestk = k;
                    }
                }
            }
            dp[l][r] = best;
            choice[l][r] = bestk;
        }
    }

    // Overall answer:
    // choose any odd-length interval [l..r], keep it to one value dp[l][r],
    // delete all outside elements from ends.
    ll ans = -(1LL << 60);
    int bestL = 1, bestR = 1;
    for (int l = 1; l <= N; l++) {
        for (int r = l; r <= N; r += 2) { // odd length
            if (((r - l) & 1) == 0) {
                if (dp[l][r] > ans) {
                    ans = dp[l][r];
                    bestL = l;
                    bestR = r;
                }
            }
        }
    }

    // Build merge tree nodes for chosen interval.
    Node *nodes = (Node*)malloc((2 * N + 5) * sizeof(Node));
    int nodeCnt = 0;

    int **root = (int**)malloc((N + 2) * sizeof(int*));
    for (int i = 0; i <= N + 1; i++) {
        root[i] = (int*)malloc((N + 2) * sizeof(int));
        for (int j = 0; j <= N + 1; j++) root[i][j] = -1;
    }

    // recursive build using manual stack
    typedef struct { int l, r, stage; } Frame;
    Frame *st = (Frame*)malloc((2 * N + 5) * sizeof(Frame));
    int top = 0;
    st[top++] = (Frame){bestL, bestR, 0};

    while (top) {
        Frame cur = st[--top];
        int l = cur.l, r = cur.r;
        if (root[l][r] != -1) continue;
        if (l == r) {
            root[l][r] = ++nodeCnt;
            nodes[nodeCnt].kind = 0;
            continue;
        }
        if (cur.stage == 0) {
            st[top++] = (Frame){l, r, 1};
            int k = choice[l][r];
            st[top++] = (Frame){k + 1, r, 0};
            st[top++] = (Frame){l, k - 1, 0};
        } else {
            int k = choice[l][r];
            root[l][r] = ++nodeCnt;
            nodes[nodeCnt].kind = 1;
            nodes[nodeCnt].left = root[l][k - 1];
            nodes[nodeCnt].mid = k;
            nodes[nodeCnt].right = root[k + 1][r];
        }
    }

    // Simulate operations on current sequence [1..N].
    int *L = (int*)malloc((N + 2) * sizeof(int));
    int *R = (int*)malloc((N + 2) * sizeof(int));
    int aliveHead = 1, aliveTail = N;
    for (int i = 1; i <= N; i++) {
        L[i] = i - 1;
        R[i] = i + 1;
    }
    R[N] = 0;

    Op *ops = (Op*)malloc((2 * N + 5) * sizeof(Op));
    int opCnt = 0;

    int *repr = (int*)malloc((2 * N + 5) * sizeof(int)); // representative alive index of subtree root node

    // delete left outside
    while (aliveHead < bestL) {
        ops[opCnt++] = (Op){0, 1};
        int x = aliveHead;
        aliveHead = R[x];
        if (aliveHead) L[aliveHead] = 0;
    }
    // delete right outside
    while (aliveTail > bestR) {
        int lenPos = 1;
        // right end index in current sequence
        int x = aliveTail;
        int y = aliveHead;
        while (y != x) { lenPos++; y = R[y]; }
        ops[opCnt++] = (Op){0, lenPos};
        aliveTail = L[x];
        if (aliveTail) R[aliveTail] = 0;
    }

    // iterative postorder traversal to emit subtree operations
    typedef struct { int u, stage; } TFrame;
    TFrame *ts = (TFrame*)malloc((2 * N + 5) * sizeof(TFrame));
    int ttop = 0;
    int rootNode = root[bestL][bestR];
    ts[ttop++] = (TFrame){rootNode, 0};

    while (ttop) {
        TFrame cur = ts[--ttop];
        int u = cur.u;
        if (nodes[u].kind == 0) {
            // leaf: representative is its original index
            // it is still alive at this moment
            // find corresponding original index in [bestL..bestR]
            // root intervals were unique; leaf nodes correspond in creation order only by structure,
            // so recover by scanning root table is awkward.
            // Instead, for leaf node kind=0, store left as index. Reuse field.
            if (nodes[u].left == 0) {
                // need initialize; impossible to know now if not stored
            }
        }
    }

    // Rebuild nodes with leaf indices stored explicitly.
    nodeCnt = 0;
    for (int i = 0; i <= N + 1; i++)
        for (int j = 0; j <= N + 1; j++)
            root[i][j] = -1;

    top = 0;
    st[top++] = (Frame){bestL, bestR, 0};
    while (top) {
        Frame cur = st[--top];
        int l = cur.l, r = cur.r;
        if (root[l][r] != -1) continue;
        if (l == r) {
            root[l][r] = ++nodeCnt;
            nodes[nodeCnt].kind = 0;
            nodes[nodeCnt].left = l; // store original index
            continue;
        }
        if (cur.stage == 0) {
            st[top++] = (Frame){l, r, 1};
            int k = choice[l][r];
            st[top++] = (Frame){k + 1, r, 0};
            st[top++] = (Frame){l, k - 1, 0};
        } else {
            int k = choice[l][r];
            root[l][r] = ++nodeCnt;
            nodes[nodeCnt].kind = 1;
            nodes[nodeCnt].left = root[l][k - 1];
            nodes[nodeCnt].mid = k;
            nodes[nodeCnt].right = root[k + 1][r];
        }
    }

    ttop = 0;
    ts[ttop++] = (TFrame){rootNode, 0};
    while (ttop) {
        TFrame cur = ts[--ttop];
        int u = cur.u;
        if (nodes[u].kind == 0) {
            repr[u] = nodes[u].left;
            continue;
        }
        if (cur.stage == 0) {
            ts[ttop++] = (TFrame){u, 1};
            ts[ttop++] = (TFrame){nodes[u].right, 0};
            ts[ttop++] = (TFrame){nodes[u].left, 0};
        } else {
            int x = repr[nodes[u].left];
            int z = repr[nodes[u].right];
            int y = nodes[u].mid;

            // At this moment, subtree [left..right] should still exist as x - y - z consecutively.
            // Need current position of y in alive sequence.
            int pos = 1;
            int p = aliveHead;
            while (p != y) {
                pos++;
                p = R[p];
            }
            ops[opCnt++] = (Op){1, pos};

            // remove x and z, keep y as representative
            int lx = L[x];
            int rz = R[z];
            if (lx) R[lx] = y; else aliveHead = y;
            if (rz) L[rz] = y; else aliveTail = y;
            L[y] = lx;
            R[y] = rz;

            repr[u] = y;
        }
    }

    printf("%lld\n", ans);
    printf("%d\n", opCnt);
    for (int i = 0; i < opCnt; i++) {
        printf("%d\n", ops[i].idx);
    }

    free(a);
    for (int i = 0; i <= N + 1; i++) {
        free(dp[i]);
        free(choice[i]);
        free(root[i]);
    }
    free(dp);
    free(choice);
    free(root);
    free(nodes);
    free(st);
    free(ts);
    free(L);
    free(R);
    free(ops);
    free(repr);

    return 0;
}

