#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct Choice {
    int type; // 0: take left end, 1: take right end, 2: take middle
    int k;    // for type 2, split point k (i..k-1 , k+1..j)
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> a(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];

    // dp[i][j] = maximum value obtainable from subarray [i..j]
    vector<vector<int64>> dp(N + 2, vector<int64>(N + 2, LLONG_MIN));
    vector<vector<Choice>> pre(N + 2, vector<Choice>(N + 2, {-1, -1}));

    for (int i = 1; i <= N; ++i) {
        dp[i][i] = a[i];
    }

    for (int len = 2; len <= N; ++len) {
        for (int i = 1; i + len - 1 <= N; ++i) {
            int j = i + len - 1;

            // choose left end first -> remaining [i+1..j]
            if (dp[i + 1][j] > dp[i][j]) {
                dp[i][j] = dp[i + 1][j];
                pre[i][j] = {0, -1};
            }

            // choose right end first -> remaining [i..j-1]
            if (dp[i][j - 1] > dp[i][j]) {
                dp[i][j] = dp[i][j - 1];
                pre[i][j] = {1, -1};
            }

            // choose a middle element p, then result is
            // best([i..p-1]) + best([p+1..j])
            // This is possible iff p is not an end, i.e. i < p < j.
            // Equivalently split at k=p, combining [i..k-1] and [k+1..j].
            for (int p = i + 1; p <= j - 1; ++p) {
                int64 cand = dp[i][p - 1] + dp[p + 1][j];
                if (cand > dp[i][j]) {
                    dp[i][j] = cand;
                    pre[i][j] = {2, p};
                }
            }
        }
    }

    // Reconstruct one valid sequence of chosen positions in the CURRENT sequence.
    vector<int> ops;

    function<void(int,int, vector<int>&)> build = [&](int i, int j, vector<int>& ids) {
        if (i == j) return;
        Choice c = pre[i][j];
        if (c.type == 0) {
            // choose left end: current position 1
            ops.push_back(1);
            vector<int> nxt(ids.begin() + 1, ids.end());
            build(i + 1, j, nxt);
        } else if (c.type == 1) {
            // choose right end: current position size
            ops.push_back((int)ids.size());
            vector<int> nxt(ids.begin(), ids.end() - 1);
            build(i, j - 1, nxt);
        } else {
            int p = c.k;
            int pos = p - i + 1; // position in current sequence
            ops.push_back(pos);

            vector<int> leftIds(ids.begin(), ids.begin() + (p - i));
            vector<int> rightIds(ids.begin() + (p - i + 1), ids.end());

            build(i, p - 1, leftIds);
            build(p + 1, j, rightIds);
        }
    };

    vector<int> ids(N);
    iota(ids.begin(), ids.end(), 1);
    build(1, N, ids);

    cout << dp[1][N] << '\n';
    for (int x : ops) cout << x << '\n';

    return 0;
}

