public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] a = new long[N + 1];
        for (int i = 1; i <= N; i++) a[i] = fs.nextLong();

        long sumOdd = 0, sumEven = 0;
        boolean hasPos = false;
        for (int i = 1; i <= N; i++) {
            if (a[i] > 0) {
                hasPos = true;
                if ((i & 1) == 1) sumOdd += a[i];
                else sumEven += a[i];
            }
        }

        StringBuilder out = new StringBuilder();
        List<Integer> ops = new ArrayList<>();
        long ans;

        if (!hasPos) {
            int p = 1;
            for (int i = 2; i <= N; i++) {
                if (a[i] > a[p]) p = i;
            }
            ans = a[p];
            for (int i = 1; i < p; i++) ops.add(1);
            int curLen = N - (p - 1);
            while (curLen > 1) {
                ops.add(curLen);
                curLen--;
            }
        } else {
            int parity = (sumOdd >= sumEven) ? 1 : 0; // 1=>odd, 0=>even
            ans = Math.max(sumOdd, sumEven);

            List<Integer> good = new ArrayList<>();
            for (int i = 1; i <= N; i++) {
                if ((i & 1) == parity && a[i] > 0) good.add(i);
            }

            int first = good.get(0);
            int last = good.get(good.size() - 1);

            for (int i = 1; i < first; i++) ops.add(1);

            int curLen = N - (first - 1);
            for (int i = N; i > last; i--) {
                ops.add(curLen);
                curLen--;
            }

            for (int idx = 0; idx + 1 < good.size(); idx++) {
                int gapPairs = (good.get(idx + 1) - good.get(idx)) / 2;
                for (int t = 0; t < gapPairs - 1; t++) {
                    ops.add(3);
                    curLen -= 2;
                }
                ops.add(2);
                curLen -= 2;
            }
        }

        out.append(ans).append('\n');
        out.append(ops.size()).append('\n');
        for (int x : ops) out.append(x).append('\n');
        System.out.print(out);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sgn;
        }
    }
